import{_ as e,o,c as r,a2 as n}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"Ceph RGW Refactoring Meeting 2025-02-19","description":"","frontmatter":{"title":"Ceph RGW Refactoring Meeting 2025-02-19","date":"2025-02-19T00:00:00.000Z","updated":"2025-02-27T00:00:00.000Z","tags":["Ceph","RGW","分布式存储","权限管理","性能优化"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/Ceph_RGW_Refactoring_Meeting_2025-02-19.md","filePath":"posts/2025/Ceph_RGW_Refactoring_Meeting_2025-02-19.md","lastUpdated":1780460162000}'),a={name:"posts/2025/Ceph_RGW_Refactoring_Meeting_2025-02-19.md"};function s(i,t,l,g,c,p){return o(),r("div",null,[...t[0]||(t[0]=[n('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议主题</strong>: Ceph RGW 开发会议</p><p><strong>日期</strong>: 2025年2月19日</p><p><strong>主持人</strong>: 未知</p><p><strong>参会人员</strong>: Adam, Casey, Cena, Matt 及其他相关开发人员</p><h4 id="_1-bucket-logging-权限问题" tabindex="-1">1. <strong>Bucket Logging 权限问题</strong> <a class="header-anchor" href="#_1-bucket-logging-权限问题" aria-label="Permalink to &quot;1. **Bucket Logging 权限问题**&quot;">​</a></h4><ul><li><strong>讨论内容</strong>: 当前Bucket Logging实现存在权限问题，导致用户可能获得超出预期的权限。</li><li><strong>解决方案讨论</strong>: 讨论了AWS的解决方案，即引入全局日志用户并通过策略或ACL控制权限，以及是否增强Bucket Policy以允许特定用户写入日志。</li><li><strong>决定</strong>: 需要进一步讨论和反馈，以决定是否引入Service Principal并增强Policy支持。</li></ul><h4 id="_2-bucket-delete-性能问题" tabindex="-1">2. <strong>Bucket Delete 性能问题</strong> <a class="header-anchor" href="#_2-bucket-delete-性能问题" aria-label="Permalink to &quot;2. **Bucket Delete 性能问题**&quot;">​</a></h4><ul><li><strong>讨论内容</strong>: 删除包含大量对象的Bucket时，并发删除操作可能导致OSD负载过高，影响集群性能。</li><li><strong>解决方案讨论</strong>: 讨论了减少并发删除操作、先删除对象再删除OMAP对象等方法。</li><li><strong>决定</strong>: 需要与Mark Nelson讨论，优化删除操作的性能。</li></ul><h4 id="_3-copy-object-加密问题" tabindex="-1">3. <strong>Copy Object 加密问题</strong> <a class="header-anchor" href="#_3-copy-object-加密问题" aria-label="Permalink to &quot;3. **Copy Object 加密问题**&quot;">​</a></h4><ul><li><strong>讨论内容</strong>: 关于Copy Object加密的PR被Stale Bot关闭，Cena重新打开了该PR。</li><li><strong>解决方案讨论</strong>: 需要将PR更新到当前代码库，并整合测试用例。</li><li><strong>决定</strong>: Cena将继续推动PR的完成，并整合测试用例。</li></ul><h4 id="_4-s3-测试问题" tabindex="-1">4. <strong>S3 测试问题</strong> <a class="header-anchor" href="#_4-s3-测试问题" aria-label="Permalink to &quot;4. **S3 测试问题**&quot;">​</a></h4><ul><li><strong>讨论内容</strong>: S3测试在最近的Fedora版本上无法运行，原因是boto core版本的问题。</li><li><strong>解决方案讨论</strong>: 通过取消对旧版本的依赖解决大部分问题，但禁用了Sig V2测试。</li><li><strong>决定</strong>: 该PR将尽快合并。</li></ul><h4 id="_5-s3-测试与sef-repo的整合问题" tabindex="-1">5. <strong>S3 测试与SEF Repo的整合问题</strong> <a class="header-anchor" href="#_5-s3-测试与sef-repo的整合问题" aria-label="Permalink to &quot;5. **S3 测试与SEF Repo的整合问题**&quot;">​</a></h4><ul><li><strong>讨论内容</strong>: 讨论了是否将S3测试移入SEF Repo，以简化测试流程。</li><li><strong>解决方案讨论</strong>: 提出了通过Toy命令简化测试流程，但仍需解决回滚问题。</li><li><strong>决定</strong>: 需要进一步讨论，是否找到S3测试的维护者，或者将S3测试整合到SEF Repo中。</li></ul><p><strong>后续行动计划</strong>:</p><ol><li><strong>Bucket Logging权限问题</strong>: 继续讨论是否引入Service Principal，并增强Policy支持。</li><li><strong>Bucket Delete性能问题</strong>: 与Mark Nelson进一步讨论，优化删除操作的性能。</li><li><strong>Copy Object加密问题</strong>: Cena继续推动PR的完成，并整合测试用例。</li><li><strong>S3测试与SEF Repo的整合问题</strong>: 寻找S3测试的维护者，或讨论是否将S3测试整合到SEF Repo中。</li></ol><p><strong>会议结束时间</strong>: 超时</p>',18)])])}const h=e(a,[["render",s]]);export{u as __pageData,h as default};
